"""Build public timing metadata; the complete local SRT remains unpublished."""
import json,pathlib
p=pathlib.Path(__file__).parent
d=json.loads((p/'timings.json').read_text())
scenes=d['scenes']
(p/'assets/scenes-data.js').write_text('window.BUYX_SCENES='+json.dumps(scenes,ensure_ascii=False)+';\nwindow.BUYX_PLAYER={duration:'+str(d['duration'])+",format(seconds){const t=Math.max(0,Math.floor(seconds));return String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');}};\n")
fmt=lambda s:f'{int(s)//60:02}:{int(s)%60:02}'
text='''# Überprüfte Argumentstellen – Alena Buyx\n\n## Referenz und Verfahren\n\nReferenz: bereitgestellte Datei `Darf Medizin alles, was sie kann, Alena Buyx.mp4`, Dauer 54:26,908.\n\nVideo-SHA-256: `'''+d['videoSha256']+'''`.\n\nDie Tonspur wurde lokal mit MacWhisper 15.6 und dem bereits installierten Modell `whisperkit:openai_whisper-small` (Deutsch) über die ganze Filmlänge in zeitcodierte SRT-Segmente transkribiert. Jede der 32 Karten wurde inhaltlich einer gesprochenen Passage zugeordnet; die Zeitgrenzen stammen aus deren SRT-Segmenten, nicht aus Wortanteilen oder PDF-Seiten. Die Segmentnummern unten machen die Zuordnung in der lokalen Arbeitsfassung prüfbar.\n\nSRT-SHA-256: `'''+d['transcriptSha256']+'''`.\n\n„Überprüft“ bedeutet: inhaltlicher Abgleich mit dem zeitcodierten Transkript genau dieser Filmdatei. Die Zeitgrenzen sind automatische Segmentgrenzen, keine manuell abgehörte, wortgenaue Vermessung. Erkennungsfehler im Transkript sind möglich; die Abschnitte sind deshalb als zusammenhängende Argumentpassagen gewählt. Der Player zeigt Zeiten auf ganze Sekunden abgerundet an und verwendet intern die genaueren Segmentzeiten.\n\nDie Karten bleiben sinngemässe didaktische Rekonstruktionen. Ihre Reihenfolge folgt den Themenblöcken; die Playernavigation folgt der Filmreihenfolge. Einzelne Karten teilen eine Passage oder überlappen. Ein Schluss kann sich auf weitere Stellen stützen, während der direkte Link zur hier angegebenen tragenden Passage führt.\n\nVollständiges SRT und Film werden nicht veröffentlicht. Die MP4 muss einmal lokal geöffnet werden; Szenenlinks funktionieren danach direkt. Bei abweichender Laufzeit warnt der Player.\n\n## Zuordnung\n\n| Karte | Filmstelle | SRT-Segmente | Inhalt der Passage |\n|---|---|---|---|\n'''
text = text.replace('## Zuordnung', 'Die Zusatzsegmentnummern P003–P017 stammen aus einer gesonderten Nachtranskription des Ausschnitts 33:00–34:15 (lokale Zeit plus 1980 Sekunden). Sie schliesst für A021 und A022 eine Erkennungslücke des langen Durchlaufs. Zusatz-SRT-SHA-256: `'+d['supplementSha256']+'`.\n\n## Zuordnung')
for k,t in scenes.items():text+=f'| {k} | {fmt(t["start"])}–{fmt(t["end"])} | {t["cues"][0]}–{t["cues"][-1]} | {t["context"]} |\n'
(p/'ZEITMARKEN.md').write_text(text)
